using namespace std;
static inline uint32_t pack4(uint8_t x,uint8_t y,uint8_t dx,uint8_t dy){return (uint32_t)x|((uint32_t)y<<8)|((uint32_t)dx<<16)|((uint32_t)dy<<24);} 
static inline void unpack4(uint32_t s,uint8_t &x,uint8_t &y,uint8_t &dx,uint8_t &dy){x=s&255;y=(s>>8)&255;dx=(s>>16)&255;dy=(s>>24)&255;}
struct TC{int h;uint8_t mask;TC(int H):h(H),mask((1u<<H)-1){}
 uint32_t reduce(uint32_t s)const{uint8_t x,y,dx,dy;unpack4(s,x,y,dx,dy);if(x&(1u<<(h-1))){x^=mask;y^=mask;}return pack4(x,y,dx,dy);} 
 uint32_t trans(uint32_t s,int c,int l)const{uint8_t x,y,dx,dy;unpack4(s,x,y,dx,dy);int ta=l>=0?l+1:1,tb=l<0?-l+1:1,na=h+ta,nb=h+tb;int16_t L[17][17];L[h][h]=h;int cur=h;for(int k=h-1;k>=0;--k){cur-=(dx>>(h-1-k))&1;L[k][h]=cur;}cur=h;for(int k=h-1;k>=0;--k){cur-=(dy>>(h-1-k))&1;L[h][k]=cur;}
 auto ac=[&](int i){if(i<=h)return int((x>>(h-i))&1);int q=i-h-1;if(l>=0)return q<l?1-c:c;return c;}; auto bc=[&](int j){if(j<=h)return int((y>>(h-j))&1);int q=j-h-1;if(l<0)return q<(-l)?1-c:c;return c;};
 for(int i=0;i<=na;i++)for(int j=0;j<=nb;j++)if(i>h||j>h){if(i==0)L[i][j]=L[i][j-1];else if(j==0)L[i][j]=L[i-1][j];else if(ac(i)==bc(j))L[i][j]=L[i-1][j-1]+1;else L[i][j]=max(L[i][j-1],L[i-1][j]);}
 int i=na,j=nb;while(i>=h&&j>=h){if(L[i][j]==L[i-1][j])--i;else if(L[i][j]==L[i][j-1])--j;else{--i;--j;}if(i==h&&j==h){uint8_t xs=x,ys=y;if(l>=0){for(int q=0;q<l;q++)xs=((xs<<1)|(1-c))&mask;xs=((xs<<1)|c)&mask;ys=((ys<<1)|c)&mask;}else{xs=((xs<<1)|c)&mask;for(int q=0;q<-l;q++)ys=((ys<<1)|(1-c))&mask;ys=((ys<<1)|c)&mask;}uint8_t ndx=0,ndy=0;for(int k=na-h+1;k<=na;k++)ndx=(ndx<<1)|(L[k][nb]-L[k-1][nb]);for(int k=nb-h+1;k<=nb;k++)ndy=(ndy<<1)|(L[na][k]-L[na][k-1]);return reduce(pack4(xs,ys,ndx,ndy));}}
 return UINT32_MAX;}
};
struct Graph{int h,deg;vector<uint32_t> states,tr;};
Graph build(int h){TC tc(h);uint32_t start=tc.reduce(pack4(0,0,(1u<<h)-1,(1u<<h)-1));unordered_map<uint32_t,uint32_t> idx;size_t reserveN=h==7?900000:150000;idx.reserve(reserveN);idx.max_load_factor(.75);vector<uint32_t> st;st.reserve(reserveN);st.push_back(start);idx[start]=0;int nl=2*h-1,deg=2*nl;vector<uint32_t> tr;for(size_t head=0;head<st.size();head++){uint32_t s=st[head];for(int c=0;c<2;c++)for(int l=-(h-1);l<=h-1;l++){uint32_t t=tc.trans(s,c,l),out=UINT32_MAX;if(t!=UINT32_MAX){auto it=idx.find(t);if(it==idx.end()){out=st.size();idx.emplace(t,out);st.push_back(t);}else out=it->second;}tr.push_back(out);}}return{h,deg,move(st),move(tr)};}
long double wt(int h,int l,long double x,long double y){int a=abs(l);if(a<=h-2)return l>=0?powl(x,a+1)*y:x*powl(y,a+1);return l>=0?powl(x,h)*y/(1-x):x*powl(y,h)/(1-y);}
long double base_rho(const Graph&G,long double x,long double y){size_t N=G.states.size();int h=G.h,nl=2*h-1;vector<double> W(nl);for(int i=0;i<nl;i++)W[i]=(double)wt(h,i-(h-1),x,y);vector<double>v(N,1),u(N);for(int it=0;it<120;it++){double mx=0;for(size_t i=0;i<N;i++){double s=0;auto*r=&G.tr[i*G.deg];for(int c=0;c<2;c++)for(int li=0;li<nl;li++){auto d=r[c*nl+li];if(d!=UINT32_MAX)s+=W[li]*v[d];}u[i]=s;mx=max(mx,s);}for(auto&q:u)q/=mx;v.swap(u);}long double lo=1e100L,hi=0;for(size_t i=0;i<N;i++){long double s=0;auto*r=&G.tr[i*G.deg];for(int c=0;c<2;c++)for(int li=0;li<nl;li++){auto d=r[c*nl+li];if(d!=UINT32_MAX)s+=W[li]*v[d];}long double rr=s/v[i];lo=min(lo,rr);hi=max(hi,rr);}return (lo+hi)/2;}
long double filtered_rho(const Graph&G,long double x,long double y){size_t N=G.states.size(),M=5*N;int h=G.h,nl=2*h-1;vector<double>W(nl);for(int i=0;i<nl;i++)W[i]=(double)wt(h,i-(h-1),x,y);vector<double>v(M,1),u(M);for(int it=0;it<160;it++){double mx=0;
#pragma omp parallel for reduction(max:mx) schedule(static)
 for(long long ii=0;ii<(long long)N;ii++){auto*r=&G.tr[(size_t)ii*G.deg];double s[5]={0,0,0,0,0};for(int c=0;c<2;c++)for(int li=0;li<nl;li++){auto d=r[c*nl+li];if(d==UINT32_MAX)continue;int l=li-(h-1),nm=0;if(abs(l)==2)nm=(c==0?(l>0?1:2):(l>0?3:4));s[nm]+=W[li]*v[(size_t)d*5+nm];}double total=s[0]+s[1]+s[2]+s[3]+s[4];double o[5]={total,total-s[2],total-s[1],total-s[4],total-s[3]};for(int m=0;m<5;m++){u[(size_t)ii*5+m]=o[m];mx=max(mx,o[m]);}}for(size_t k=0;k<M;k++)u[k]/=mx;v.swap(u);}double lo=1e100,hi=0;
#pragma omp parallel for reduction(min:lo) reduction(max:hi) schedule(static)
 for(long long ii=0;ii<(long long)N;ii++){auto*r=&G.tr[(size_t)ii*G.deg];double s[5]={0,0,0,0,0};for(int c=0;c<2;c++)for(int li=0;li<nl;li++){auto d=r[c*nl+li];if(d==UINT32_MAX)continue;int l=li-(h-1),nm=0;if(abs(l)==2)nm=(c==0?(l>0?1:2):(l>0?3:4));s[nm]+=W[li]*v[(size_t)d*5+nm];}double total=s[0]+s[1]+s[2]+s[3]+s[4];double o[5]={total,total-s[2],total-s[1],total-s[4],total-s[3]};for(int m=0;m<5;m++){double rr=o[m]/v[(size_t)ii*5+m];lo=min(lo,rr);hi=max(hi,rr);}}return (lo+hi)/2;}
vector<pair<int,int>> path_bfs(uint32_t start,uint32_t target,size_t limit){TC tc(8);unordered_map<uint32_t,int> idx;idx.reserve(limit*2);idx.max_load_factor(.7);vector<uint32_t>q{start};struct P{int p;int c,l;};vector<P>par{{-1,0,0}};idx[start]=0;size_t head=0;while(head<q.size()&&q.size()<limit){uint32_t s=q[head];for(int c=0;c<2;c++)for(int l=-7;l<=7;l++){uint32_t t=tc.trans(s,c,l);if(t==UINT32_MAX||idx.count(t))continue;int ni=q.size();idx[t]=ni;q.push_back(t);par.push_back({(int)head,c,l});if(t==target){vector<pair<int,int>>ans;for(int k=ni;k>0;k=par[k].p)ans.push_back({par[k].c,par[k].l});reverse(ans.begin(),ans.end());return ans;}}head++;}return{};}
